<?php /* VIVA NOTE: Read-only list of property verification stages; landlord cannot approve their own listing. */ ?><div class="toolbar"><p>Your property verification lifecycle. Only Field Agents and Admins can finalize approvals.</p></div><section class="panel table-wrap" tabindex="0" aria-label="Verification table, scroll horizontally"><table><thead><tr><th>Property</th><th>Status</th><th>Requested</th><th></th></tr></thead><tbody><?php foreach($properties as $p):?><tr><td><?=e($p['title'])?></td><td><span class="status"><?=e(pill($p['verification_status']))?></span></td><td><?=e(date_label($p['verification_submitted_at']))?></td><td><a href="<?=e(url('/property/show',['id'=>$p['property_id']]))?>">Details →</a></td></tr><?php endforeach;?><?php if(!$properties):?><tr><td class="empty" colspan="4">No properties available for verification.</td></tr><?php endif;?></tbody></table></section><div class="alert info">Your property will be listed as verified after the inspection and approval process is completed.</div>
